from __future__ import annotations

import base64
import shutil
from datetime import datetime
from pathlib import Path

INSTALLER_VERSION = "3.8.0-FAILURE-DRIVEN-MASTERY-INSTALLER"
MODULE_NAME = "alliance_failure_driven_mastery_v380.py"
REGISTRAR = "alliance_optional_property_modules.py"
MODULE_B64 = ''

REQUIRED_FILES = [
    "alliance_blind_failure_learning_v360.py",
    "alliance_autonomous_property_brain_v370.py",
    REGISTRAR,
]
REQUIRED_MARKERS = {
    "alliance_blind_failure_learning_v360.py": ["3.6.0-BLIND-FAILURE-LEARNING-NEW-UNSEEN-EXAM", "BLIND_AUDIT_V2_2026_09_03"],
    "alliance_autonomous_property_brain_v370.py": ["3.7.0-AUTONOMOUS-PROPERTY-BRAIN-TEACHER", "/property-brain/autonomous-v370"],
    REGISTRAR: ["FOUNDATION 3.7 - Autonomous Property Brain Teacher", "alliance_autonomous_property_brain_v370"],
}

REG_BLOCK = r"""

    # FOUNDATION 3.8 - Failure-Driven Mastery + Automated Routine Training
    # Learns only from already-frozen V2 human truth, suppresses duplicate source messages,
    # repairs class/transaction semantics, and freezes a NEW V3 certification set.
    # Routine labeling is automated. V3 remains independent certification only.
    # No production/WhatsApp/Gold mutations.
    try:
        if _route_exists(app, "/api/property-brain/mastery-v380/status"):
            result["mastery_v380"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/mastery-v380","error":None}
        else:
            import alliance_failure_driven_mastery_v380 as mastery_v380
            result["mastery_v380"] = {**mastery_v380.register(core), "error": None}
    except Exception as exc:
        result["mastery_v380"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/mastery-v380","fail_safe":True}
"""


def syntax_ok(path: Path):
    compile(path.read_text(encoding="utf-8"), str(path), "exec")


def main():
    root = Path.cwd()
    missing = [f for f in REQUIRED_FILES if not (root / f).exists()]
    if missing:
        raise SystemExit("Missing required current Foundation files: " + ", ".join(missing))

    for name, markers in REQUIRED_MARKERS.items():
        txt = (root / name).read_text(encoding="utf-8")
        for marker in markers:
            if marker not in txt:
                raise SystemExit(f"Safety stop: {name} is missing required marker: {marker}")

    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup_dir = root / f"backup-before-v380-{timestamp}"
    backup_dir.mkdir(exist_ok=False)
    for name in REQUIRED_FILES:
        shutil.copy2(root / name, backup_dir / name)

    module_file = root / MODULE_NAME
    module_file.write_bytes(base64.b64decode(MODULE_B64))
    syntax_ok(module_file)

    registrar_file = root / REGISTRAR
    registrar = registrar_file.read_text(encoding="utf-8")
    if "FOUNDATION 3.8 - Failure-Driven Mastery" not in registrar:
        anchor = "\n    return result"
        pos = registrar.rfind(anchor)
        if pos < 0:
            raise SystemExit("Safety stop: could not find final 'return result' in registrar. Backup was created; no registrar change made.")
        registrar = registrar[:pos] + REG_BLOCK + registrar[pos:]
        registrar_file.write_text(registrar, encoding="utf-8")
    syntax_ok(registrar_file)

    after = registrar_file.read_text(encoding="utf-8")
    historical = [
        "FOUNDATION 2.9.4 - Autonomous Gold Teacher",
        "FOUNDATION 3.0 - Autonomous Expertise Loop",
        "FOUNDATION 3.1 - Autonomous Expertise Bootcamp",
        "FOUNDATION 3.2 - Mastery Repair + Blind Holdout Gate",
        "FOUNDATION 3.3 - Ownership Mastery + Frozen Blind Set",
        "FOUNDATION 3.4 - Mastery Finalizer + Minimal Blind Audit",
        "FOUNDATION 3.5 - Training Gate Finalizer",
        "FOUNDATION 3.6 - blind failure learning + new frozen unseen exam",
        "FOUNDATION 3.7 - Autonomous Property Brain Teacher",
        "FOUNDATION 3.8 - Failure-Driven Mastery",
    ]
    lost = [m for m in historical if m not in after]
    if lost:
        shutil.copy2(backup_dir / REGISTRAR, registrar_file)
        raise SystemExit("Regression stop: registrar lost historical markers: " + ", ".join(lost))

    print("=" * 76)
    print("Alliance Property Brain Foundation 3.8 installed successfully")
    print("=" * 76)
    print("Module:", MODULE_NAME)
    print("Dashboard: /property-brain/mastery-v380")
    print("API status: /api/property-brain/mastery-v380/status")
    print("Routine labeling: AUTOMATED")
    print("Duplicate suppression: AUTOMATED")
    print("Frozen Exam V2: PRESERVED FOREVER")
    print("New V3: FROZEN INDEPENDENT CERTIFICATION ONLY")
    print("Production/WhatsApp/Gold mutations: 0")
    print("Backup:", backup_dir)
    print("Syntax validation: built-in compile() PASS (no pycache)")

if __name__ == "__main__":
    main()
